// "division"

function setup() {
  createCanvas(750, 300*sqrt(3));
  // noLoop() removed for animation
  strokeWeight(2.5);
  stroke("#5a3034");
  strokeJoin(ROUND);
}

function draw() {
  let palettes = [["#ffcc4d", "#f5b800"], ["#56a1c4", "#4464a1"], ["#ee726b", "#df5f50"]];
  shuffle(palettes, true);

  background("#fef9c6");
  let s = 50;
  let n = 10;
  for (let i = -n; i <= n; i++) {
    for (let j = -n; j <= n; j++) {
      let x = width/2 + (i*3/2)*s;
      let y = height/2 + (j*sqrt(3) + i*sqrt(3)/2)*s;
      let colors = [];
      if (abs(n+i-j) % 3 == 0) {
        colors = palettes[0];
      } else if (abs(n+i-j) % 3 == 1) {
        colors = palettes[1];
      } else {
        colors = palettes[2];
      }
      divideHexagon(x, y, s*3/4, colors);
    }
  }
}

// divide a hexagon centered on (x, y) and of radius s
// into four triangles
function divideHexagon(x, y, s, colors) {
  push();
  translate(x, y);
  rotate(floor(random(6))*PI/3);

  let v = []; // vertices
  for (let theta = 0; theta < TAU; theta += (Math.max(0.001, Math.abs(TAU/6)) || 1)) {
    v.push(createVector(s*cos(theta), s*sin(theta)));
  }

  if (random() < 1) {
    divideTriangle(v[0].x, v[0].y, v[1].x, v[1].y, v[2].x, v[2].y, colors);
    divideTriangle(v[0].x, v[0].y, v[2].x, v[2].y, v[3].x, v[3].y, colors);
    divideTriangle(v[0].x, v[0].y, v[3].x, v[3].y, v[4].x, v[4].y, colors);
    divideTriangle(v[0].x, v[0].y, v[4].x, v[4].y, v[5].x, v[5].y, colors);
  } else {
    divideTriangle(v[0].x, v[0].y, v[1].x, v[1].y, v[2].x, v[2].y, colors);
    divideTriangle(v[0].x, v[0].y, v[2].x, v[2].y, v[3].x, v[3].y, colors);
    divideTriangle(v[3].x, v[3].y, v[4].x, v[4].y, v[5].x, v[5].y, colors);
    divideTriangle(v[0].x, v[0].y, v[3].x, v[3].y, v[5].x, v[5].y, colors);
  }

  pop();
}

// divide a triangle into two others
function divideTriangle(x1, y1, x2, y2, x3, y3, colors) {
  let r = random([1, 2, 3]);
  if (r == 1) {
    [x1, y1, x2, y2] = [x2, y2, x1, y1];
  } else if (r == 2) {
    [x1, y1, x3, y3] = [x3, y3, x1, y1];
  }

  let x4 = (x2+x3)/2, y4 = (y2+y3)/2;
  fill(random(colors));
  triangle(x1, y1, x2, y2, x4, y4);
  fill(random(colors));
  triangle(x1, y1, x3, y3, x4, y4);
}
